import{t as e}from"./book-open-Dr2beUrc.js";import{t}from"./lightbulb-C6r_rGFm.js";import{I as n,L as r,Z as i,et as a,k as o,u as s,v as c}from"./index-CIJCINOx.js";var l=a(i(),1),u=r(),d=[{term:`Phân phối (Distribution)`,desc:`Coin bắt đầu 'xả' — mất động lượng tăng, tích tụ áp lực bán và sắp giảm mạnh. Tính toán tự động bởi AI từ dữ liệu định lượng 5 phút.`},{term:`Độ chính xác (Precision)`,desc:`Trong 100 lần AI báo 'sắp xả', bao nhiêu lần giá thực sự sụt giảm ≥ 8%? Đảo Vàng đạt độ chính xác thực nghiệm cao, vượt trội so với các mốc chuẩn ngẫu nhiên.`},{term:`Tỷ lệ bắt được (Recall)`,desc:`Trong 100 lần coin THẬT SỰ xả, AI bắt được bao nhiêu? Tỷ lệ bắt sóng của Đảo Vàng đạt ~60.1% trên tập dữ liệu kiểm định 600k+ nến.`},{term:`Điểm Brier (Độ chuẩn xác)`,desc:`Chỉ số đo lường độ sai lệch xác suất của AI. Số càng THẤP càng tốt (0 = hoàn hảo, 1 = sai hoàn toàn). Đảo Vàng đạt ~0.113.`},{term:`Thời gian báo trước (Median Lead Time)`,desc:`Khoảng thời gian từ khi AI phát tín hiệu đến khi cú xả 8% thực sự diễn ra. Trung bình khoảng ~9.8 giờ (590 phút).`},{term:`Kiểm định cuốn chiếu (Walk-Forward Validation)`,desc:`Phương pháp kiểm định theo chuỗi thời gian kết hợp Embargo Window — chỉ huấn luyện trên quá khứ và kiểm tra trên tương lai, loại bỏ 100% rủi ro nhìn trước (Zero Data Leakage).`},{term:`Khối lượng hợp đồng mở (Open Interest - OI)`,desc:`Tổng số lượng hợp đồng phái sinh đang mở. OI tăng vọt nhưng giá đi ngang/suy yếu là dấu hiệu phân phối điển hình.`},{term:`Tỷ lệ phí Funding (Funding Rate)`,desc:`Khoản phí giữa phe Long và Short trên sàn Futures. Funding dương quá cao cho thấy số đông đang FOMO mua đuổi, dễ bị bẫy xả ngược.`},{term:`Tỷ lệ Taker Sell / Buy`,desc:`Tỷ lệ khối lượng bán/mua chủ động từ lệnh thị trường. Taker Sell chiếm ưu thế cho thấy phe bán tổ chức đang xả hàng quyết liệt.`},{term:`Mức giảm mục tiêu (Target -8%)`,desc:`Tiêu chuẩn xác định cú xả: Giá sụt giảm ít nhất 8% trong khung 24h kể từ khi xuất hiện tín hiệu phân phối.`}],f=[{term:`Distribution Phase`,desc:`Asset begins offloading inventory — loses upward momentum, builds sell pressure, and enters a major markdown. Automatically computed from 5m quantitative derivatives data.`},{term:`Precision`,desc:`Out of 100 alerts issued by AI, how many actually achieve a ≥8% drawdown? DAO VANG achieves high empirical precision substantially outperforming random baselines.`},{term:`Recall (Capture Rate)`,desc:`Out of 100 actual market dumps, how many were successfully anticipated by AI? DAO VANG achieves ~60.1% recall across 600,000+ validation candles.`},{term:`Brier Score (Calibration Metric)`,desc:`Measures accuracy of probabilistic forecasts. Lower values represent better calibration (0 = perfect, 1 = completely wrong). DAO VANG achieves ~0.113.`},{term:`Median Lead Time`,desc:`The time elapsed from initial AI alert delivery until the -8% drawdown target is reached. DAO VANG provides an average median lead time of ~9.8 hours (590 min).`},{term:`Walk-Forward Validation`,desc:`Time-series validation method incorporating Embargo Windows — strictly trains on past data and evaluates on future data, eliminating 100% of lookahead bias and data leakage.`},{term:`Open Interest (OI)`,desc:`Total outstanding derivatives contracts. Surging OI accompanied by stalled or decelerating price action is a hallmark of institutional distribution.`},{term:`Funding Rate`,desc:`Periodic payment exchanged between Longs and Shorts on perpetual futures. Excessively high positive funding indicates crowded FOMO longs prone to liquidation cascades.`},{term:`Taker Sell / Buy Ratio`,desc:`Ratio of market orders initiated by aggressive sellers vs buyers. Dominant Taker Sell volume reflects aggressive distribution.`},{term:`Target Drawdown (-8%)`,desc:`Standard ground-truth benchmark: Price decreases by at least 8% within 24 hours of signal issuance while adverse upside drift stays ≤ 4%.`}],p=[{term:`派发阶段 (Distribution Phase)`,desc:`资产主力开始抛售筹码库存——丧失上涨动能，聚集卖方压力并进入大幅回撤。基于 5 分钟衍生品量化数据实时计算。`},{term:`精准率 (Precision)`,desc:`在 AI 发出“即将见顶”的 100 次预警中，有多少次实际跌幅 ≥ 8%？刀锋系统在实盘回测中取得了显著优于随机基准的高精准度。`},{term:`捕获率 / 召回率 (Recall)`,desc:`在市场上 100 次实际发生的暴跌行情中，AI 成功提前捕捉到了多少次？在 60 万根 K 线样本中，系统捕获率达到约 60.1%。`},{term:`布里尔分数 (Brier Score)`,desc:`衡量 AI 概率预测校准准确度的指标。数值越低越好（0 为完美预测，1 为完全相反）。刀锋系统达到约 0.113。`},{term:`提前预警时间 (Median Lead Time)`,desc:`从 AI 发出警报到价格真正触及 -8% 目标的时间差。系统平均提前约 9.8 小时（590 分钟）发出预警。`},{term:`推进式前向验证 (Walk-Forward Validation)`,desc:`严格的时序验证方法，包含 Embargo 隔离窗口——只在历史数据上训练并在未来数据上测试，100% 杜绝未来函数与数据穿越。`},{term:`未平仓合约量 (Open Interest - OI)`,desc:`衍生品未平仓总头寸。持仓量剧烈增加但价格停滞或滞涨，是机构派发抛售的典型特征。`},{term:`资金费率 (Funding Rate)`,desc:`永续合约多空双方定期交换的资金费率。费率异常高说明多头情绪过度拥挤，极易引发踩踏连环爆仓。`},{term:`主动卖出/买入比率 (Taker Sell/Buy)`,desc:`市场主动吃单方向的成交比。主动卖单占主导地位反映机构正在坚决出货。`},{term:`目标回撤 (Target -8%)`,desc:`判定暴跌的标准基准：自信号发出起 24 小时内价格回撤至少 8%，且最大逆向波动 ≤ 4%。`}],m=[{term:`분산 국면 (Distribution Phase)`,desc:`자산이 물량을 털어내기 시작하는 단계 — 상승 모멘텀 상실, 매도 압력 누적, 급격한 하락 임박. 5분 파생상품 정량 데이터로 실시간 계산.`},{term:`정밀도 (Precision)`,desc:`AI가 '급락 예고'를 보낸 100번 중 실제로 ≥ 8% 하락한 비율. 다오방(DAO VANG)은 무작위 기준선을 크게 상회하는 실증 정밀도를 달성합니다.`},{term:`재현율 / 포착률 (Recall)`,desc:`실제 발생한 100번의 덤프 중 AI가 사전에 포착한 비율. 60만 개 이상의 캔들 데이터셋에서 약 60.1%의 포착률을 기록합니다.`},{term:`브라이어 점수 (Brier Score)`,desc:`AI 확률 예측의 보정 정확도를 측정하는 지표. 낮을수록 우수함 (0 = 완벽, 1 = 완전 오차). 다오방은 약 0.113을 달성.`},{term:`사전 경보 리드타임 (Median Lead Time)`,desc:`AI 경보 발생 시점부터 -8% 목표 하락에 도달할 때까지의 시간. 평균 약 9.8시간(590분)의 선행 여유를 제공합니다.`},{term:`전진 검증 (Walk-Forward Validation)`,desc:`엠바고 윈도우를 적용한 시계열 검증 기법 — 과거 데이터만으로 학습하고 미래 데이터로만 테스트하여 100% 데이터 누수(Lookahead Bias)를 방지.`},{term:`미결제약정 (Open Interest - OI)`,desc:`미결제 파생상품 계약 총량. OI가 급증하는 반면 가격 상승이 둔화되는 것은 전형적인 세력 분산(털기) 징후입니다.`},{term:`펀딩비 (Funding Rate)`,desc:`무기한 선물 롱/숏 간 지불 비용. 지나치게 높은 양수 펀딩비는 롱 포지션 과열 및 롱스퀴즈 취약성을 나타냅니다.`},{term:`테이커 매도 비율 (Taker Sell Ratio)`,desc:`시장가 주문 중 매도 주문이 차지하는 비율. 테이커 매도 우위는 기관의 공격적인 물량 출회를 의미합니다.`},{term:`목표 하락폭 (Target -8%)`,desc:`급락 판정 표준 기준: 신호 발생 후 24시간 이내에 가격이 최소 8% 하락하고, 역방향 상승 오차(MAE)는 4% 이하로 제한.`}],h=({isOpen:r,onClose:i})=>{let{language:a}=n(),[h,g]=l.useState(``);if(!r)return null;let _=(a===`zh`?p:a===`ko`?m:a===`en`?f:d).filter(e=>e.term.toLowerCase().includes(h.toLowerCase())||e.desc.toLowerCase().includes(h.toLowerCase()));return(0,u.jsx)(`div`,{className:`fixed inset-0 z-50 bg-slate-950/80 backdrop-blur-sm flex items-center justify-center p-4`,children:(0,u.jsxs)(`div`,{className:`bg-slate-900 border border-slate-800 rounded-2xl max-w-2xl w-full max-h-[85vh] flex flex-col shadow-2xl overflow-hidden`,children:[(0,u.jsxs)(`div`,{className:`p-4 border-b border-slate-800 flex items-center justify-between bg-slate-950`,children:[(0,u.jsxs)(`div`,{className:`flex items-center gap-2`,children:[(0,u.jsx)(o,{className:`w-5 h-5 text-amber-400`}),(0,u.jsx)(`h2`,{className:`text-base font-bold text-slate-100`,children:a===`zh`?`帮助与指标术语词典`:a===`ko`?`도움말 및 지표 용어 사전`:a===`en`?`Help & Indicator Glossary`:`Trợ giúp & Từ điển Thuật ngữ`})]}),(0,u.jsx)(`button`,{onClick:i,className:`p-1 rounded-lg text-slate-400 hover:text-white hover:bg-slate-800 transition`,children:(0,u.jsx)(s,{className:`w-5 h-5`})})]}),(0,u.jsx)(`div`,{className:`p-3 border-b border-slate-800 bg-slate-900`,children:(0,u.jsxs)(`div`,{className:`relative`,children:[(0,u.jsx)(c,{className:`w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-slate-500`}),(0,u.jsx)(`input`,{type:`text`,placeholder:a===`zh`?`搜索术语 (持仓量 OI, 精准率, 资金费率, 提前预警时间)...`:a===`ko`?`용어 검색 (OI, 정밀도, 펀딩비, 리드타임)...`:a===`en`?`Search terms (OI, Precision, Funding, Lead time)...`:`Tìm kiếm thuật ngữ (OI, độ chính xác, funding, lead time...)`,value:h,onChange:e=>g(e.target.value),className:`w-full bg-slate-950 border border-slate-800 rounded-lg pl-9 pr-3 py-2 text-xs text-slate-200 focus:outline-none focus:border-amber-500`})]})}),(0,u.jsxs)(`div`,{className:`flex-1 overflow-y-auto p-4 space-y-4`,children:[(0,u.jsxs)(`div`,{className:`text-xs text-slate-300 leading-relaxed`,children:[(0,u.jsxs)(`p`,{className:`mb-1`,children:[(0,u.jsx)(`strong`,{className:`text-amber-400`,children:a===`en`?`DAO VANG AI Radar`:a===`zh`?`刀锋 PeakPulse AI 雷达`:a===`ko`?`다오방 AI 레이더`:`Đảo Vàng AI Radar`}),` `,a===`en`?`provides early detection of distribution phases before major crypto price drops. The system continuously scans Binance Futures pairs 24/7 across multi-dimensional derivatives metrics.`:a===`zh`?`在加密资产发生暴跌之前提前捕捉派发见顶特征。系统全天候 24/7 监控 Binance 合约交易对的多维度衍生品量化指标。`:a===`ko`?`주요 암호화폐 급락이 시작되기 전 세력의 분산 국면을 사전에 포착합니다. 바이낸스 선물 페어를 24/7 지속 모니터링하여 다차원 파생상품 지표를 계산합니다.`:`giúp phát hiện sớm dấu hiệu phân phối — coin sắp xả giá. Hệ thống quét toàn bộ coin hợp đồng tương lai trên Binance 24/7, tính toán điểm số từ dữ liệu phái sinh đa chiều.`]}),(0,u.jsxs)(`ul`,{className:`list-disc list-inside space-y-0.5 text-slate-400`,children:[(0,u.jsxs)(`li`,{children:[(0,u.jsx)(`strong`,{children:a===`en`?`Distribution Score / Probability:`:a===`zh`?`派发得分 / 概率:`:a===`ko`?`분산 점수 / 확률:`:`Điểm phân phối / Xác suất:`}),` `,a===`en`?`Higher score indicates stronger confluence of distribution footprints.`:a===`zh`?`得分越高，发生剧烈回撤的概率越大。`:a===`ko`?`점수가 높을수록 분산 패턴의 합치도가 높습니다.`:`Điểm càng cao, xác suất xảy ra pha phân phối càng lớn.`]}),(0,u.jsxs)(`li`,{children:[(0,u.jsx)(`strong`,{children:a===`en`?`Target Drawdown -8%:`:a===`zh`?`目标回撤 8%:`:a===`ko`?`목표 하락 8%:`:`Mức giảm mục tiêu 8%:`}),` `,a===`en`?`Expected price drop of ≥8% within a 24h horizon.`:a===`zh`?`自信号发出起 24 小时内价格预期下跌 ≥8%。`:a===`ko`?`신호 발생 후 24시간 이내 최소 8% 하락 예상.`:`Giá giảm ít nhất 8% trong vòng 24 giờ kể từ tín hiệu.`]}),(0,u.jsxs)(`li`,{children:[(0,u.jsx)(`strong`,{children:a===`en`?`Smart Automation:`:a===`zh`?`智能自动化:`:a===`ko`?`스마트 자동화:`:`Tự động thông minh:`}),` `,a===`en`?`Instant push notifications to Telegram when probability threshold is reached.`:a===`zh`?`当概率达到设定阈值时自动向 Telegram 发送即时推送。`:a===`ko`?`확률 임계값 도달 시 텔레그램으로 즉시 알림 발송.`:`Tự động gửi cảnh báo Telegram khi điểm số đạt ngưỡng.`]})]})]}),(0,u.jsxs)(`div`,{className:`space-y-2.5`,children:[(0,u.jsxs)(`h3`,{className:`text-xs font-bold text-amber-400 uppercase tracking-wider flex items-center gap-1.5`,children:[(0,u.jsx)(e,{className:`w-3.5 h-3.5`}),a===`en`?`Detailed Concept Guide`:a===`zh`?`核心概念详解`:a===`ko`?`상세 개념 가이드`:`Giải thích chi tiết các thuật ngữ`]}),_.map((e,t)=>(0,u.jsxs)(`div`,{className:`bg-slate-950 p-3 rounded-xl border border-slate-800 space-y-1`,children:[(0,u.jsxs)(`h4`,{className:`text-xs font-bold text-slate-100 flex items-center gap-1.5`,children:[(0,u.jsx)(`span`,{className:`w-1.5 h-1.5 rounded-full bg-amber-400`}),e.term]}),(0,u.jsx)(`p`,{className:`text-xs text-slate-400 leading-relaxed pl-3`,children:e.desc})]},t))]}),(0,u.jsxs)(`div`,{className:`bg-amber-950/20 border border-amber-500/20 rounded-xl p-3 text-xs space-y-1 text-slate-300`,children:[(0,u.jsxs)(`div`,{className:`font-bold text-amber-400 flex items-center gap-1`,children:[(0,u.jsx)(t,{className:`w-3.5 h-3.5`}),a===`en`?`Trading Strategy Notice`:a===`zh`?`交易策略提示`:a===`ko`?`매매 전략 안내`:`Lưu ý khi sử dụng`]}),(0,u.jsx)(`p`,{className:`text-[11px] text-slate-400`,children:a===`en`?`DAO VANG AI provides early probabilistic risk indicators. Always practice disciplined risk management, avoid overleveraging on newly listed meme tokens, and observe BTC market regime conditions.`:a===`zh`?`刀锋 AI 提供高概率的早期风险预警。请始终执行严格的风控纪律，避免在极高波动的新币上过度杠杆，并密切结合 BTC 宏观环境。`:a===`ko`?`다오방 AI는 조기 확률적 위험 지표를 제공합니다. 항상 엄격한 리스크 관리를 준수하고, 신규 상장 밈코인에 과도한 레버리지를 피하며 BTC 시장 상황을 확인하세요.`:`Đảo Vàng AI cung cấp tín hiệu cảnh báo rủi ro mang tính xác suất. Luôn quản trị vốn cẩn trọng, tránh đòn bẩy quá lớn đối với coin mới lên sàn và theo dõi sát xu hướng của Bitcoin.`})]})]})]})})};export{h as GlossaryModal};